+    let width = window_rect.right - window_rect.left;
+    let height = window_rect.bottom - window_rect.top;
+    if width <= 0 || height <= 0 {
+        return;
+    }
+    unsafe {
+        let region = CreateRoundRectRgn(0, 0, width, height, radius * 2, radius * 2);
